import subprocess
import sys

cases = [(0, 0), (9, 0), (10, 1), (19999, 1999), (23999, 2399), (24000, 2400), (24010, 2400), (10**30, 2400)]
count = 0
for release in (None, \"1.0\"):
    for service_on in (\"2020-01-01\", \"2099-12-31\"):
        for charge, credit in cases:
            request = {\"command\": \"quote\", \"line\": {\"line_id\": \"L-雪\", \"account_id\": \"A\", \"subscription_id\": \"S\", \"service_on\": service_on, \"charge_cents\": charge}}
            if release is not None:
                request[\"release\"] = release
            result = subprocess.run([sys.executable, \"main.py\"], input=json.dumps(request), text=True, capture_output=True, check=True)
            expected = {\"release\": \"1.0\", \"line_id\": \"L-雪\", \"credit_cents\": credit, \"amount_due_cents\": charge - credit}
            actual = json.loads(result.stdout)
            assert actual == expected, (request, actual, expected)
            assert type(actual[\"credit_cents\"]) is int and type(actual[\"amount_due_cents\"]) is int
            assert result.stderr == \"\", result.stderr
            count += 1
print(f\"PASS {count} CLI boundary checks\")
'"

